def _legacy_lines(form):
    """The old (unused) treatment table rows, as text."""
    lines = []
    for n in (1, 2, 3):
        parts = [getattr(form, f"treatment_line_{n}"), getattr(form, f"treatment_units_{n}"),
                 getattr(form, f"treatment_batch_{n}")]
        price = getattr(form, f"treatment_price_{n}")
        if price is not None:
            parts.append(f"£{price}")
        if any(parts):
            lines.append(" · ".join(str(p) for p in parts if p))
    return lines


def move_treatments_to_cards(apps, schema_editor):
    Botox = apps.get_model("forms_system", "BotoxConsentForm")
    Card  = apps.get_model("forms_system", "BotoxTreatmentCard")

    numbers = {}
    for form in Botox.objects.order_by("completed_at", "pk"):
        legacy = _legacy_lines(form)
        if not (any(getattr(form, f) for f in TEXT_FIELDS) or form.treatment_cost is not None or legacy):
            continue

        when = form.operator_signed_at or form.completed_at
        numbers[form.user_id] = numbers.get(form.user_id, 0) + 1
        notes = form.operator_notes
        if legacy:
            notes = "\n".join(filter(None, [notes, "Treatment lines from the original form:", *legacy]))

        Card.objects.create(
            user_id=form.user_id,
            treatment_number=numbers[form.user_id],
            prescription_id=form.pk,
            date=when.date(),
            time=when.time().replace(second=0, microsecond=0),
            treatment_cost=form.treatment_cost,
            created_by_id=form.operator_signed_by_id,
            **{f: getattr(form, f) for f in TEXT_FIELDS if f != "operator_notes"},
            operator_notes=notes,
            **{f: getattr(form, f) for f in LIFECYCLE_FIELDS},
        )


